static void handle_client_command(int fd, char *cmd) {
    char buffer[256];
    sprintf(buffer, "EXEC: %s", cmd); // Vulnerable: buffer overflow (CWE-120)
    write(fd, buffer, strlen(buffer));
}

static void safe_handle_client_command(int fd, const char *cmd) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "EXEC: %s", cmd);
    write(fd, buffer, strnlen(buffer, sizeof(buffer)));
}
